/// <summary>
/// PricingAttribute of table <c>SalesTable</c> field VATNumRecId.
/// </summary>
/// [UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeSalesTableVATNumRecid extends UPSPricingAttributeSalesTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesTable, VATNumRecId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Int64);
    SalesTable salesTable;
    while select VATNumRecId from salesTable
        group by VATNumRecId
    {
        ret.add(salesTable.VATNumRecId);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesTable, VATNumRecId));
    qbr.value(queryValue(_value));
}
